function performMerge(mine, base, theirs, mode) {
  // Compute changes using LCS
  const mineChanges = computeChanges(base, mine);
  const theirsChanges = computeChanges(base, theirs);

  // Gather changes into regions
  const regions = gatherRegions(base, mineChanges, theirsChanges);

  // Resolve regions
  const resolved = resolveRegions(regions, base, mine, theirs);

  // Output based on mode
  let hasConflict = false;

  if (mode === 'merge' || mode === 'merge2') {
    // Output merged document
    for (const region of resolved) {
      if (region.type === 'stable') {
        for (const line of region.lines) {
          process.stdout.write(line + '\n');
        }
      } else if (region.type === 'conflict') {
        hasConflict = true;
        process.stdout.write('<<<<<<< mine\n');
        for (const line of region.mine) {
          process.stdout.write(line + '\n');
        }
        if (mode === 'merge') {
          process.stdout.write('||||||| base\n');
          for (const line of region.base) {
            process.stdout.write(line + '\n');
          }
        }
        process.stdout.write('=======\n');
        for (const line of region.theirs) {
          process.stdout.write(line + '\n');
        }
        process.stdout.write('>>>>>>> theirs\n');
      } else {
        // mine or theirs change
        for (const line of region.lines) {
          process.stdout.write(line + '\n');
        }
      }
    }
  } else {
    // regions mode: output statistics
    for (const region of resolved) {
      if (region.type === 'conflict') {
        hasConflict = true;
        process.stdout.write(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}\n`);
      } else {
        process.stdout.write(`${region.type} ${region.lines.length}\n`);
      }
    }
  }

  process.exit(hasConflict ? 1 : 0);
}

function computeChanges(base, side) {
  // Compute LCS between base and side
  const lcs = longestCommonSubsequence(base, side);

  // Extract changes as (baseStart, baseEnd, sideStart, sideEnd) tuples
  const changes = [];
  let baseIdx = 0;
  let sideIdx = 0;

  for (const match of lcs) {
    // If there's a gap between current position and match, that's a change
    if (baseIdx !== match.base || sideIdx !== match.side) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: match.base,
        sideStart: sideIdx,
        sideEnd: match.side
      });
    }
    baseIdx = match.base + 1;
    sideIdx = match.side + 1;
  }

  // Handle changes at the end
  if (baseIdx !== base.length || sideIdx !== side.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      sideStart: sideIdx,
      sideEnd: side.length
    });
  }

  return changes;
}

function longestCommonSubsequence(base, side) {
  // Find LCS with tie-breaking: prefer earlier matches
  // When advancing, prefer the side with longer remaining subsequence
  const m = base.length;
  const n = side.length;

  // Build LCS using greedy approach with proper tie-breaking
  const lcs = [];
  let i = 0;
  let j = 0;

  while (i < m && j < n) {
    if (base[i] === side[j]) {
      // Match found - take it
      lcs.push({ base: i, side: j });
      i++;
      j++;
    } else {
      // No match - decide which to advance
      const baseRemaining = m - i;
      const sideRemaining = n - j;

      // Find how far each can go
      const baseFuture = findLCSLength(base, side, i + 1, j);
      const sideFuture = findLCSLength(base, side, i, j + 1);

      if (sideFuture > baseFuture) {
        j++;
      } else if (baseFuture > sideFuture) {
        i++;
      } else {
        // Tie - prefer base
        i++;
      }
    }
  }

  return lcs;
}

function findLCSLength(base, side, i, j) {
  // Quick LCS length calculation
  const m = base.length;
  const n = side.length;

  let len = 0;
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      len++;
      i++;
      j++;
    } else {
      // Simple scan ahead
      let iAhead = i, jAhead = j;
      let lenAhead = 0;
      const baseRemaining = m - i;
      const sideRemaining = n - j;

      if (baseRemaining > sideRemaining) {
        iAhead++;
      } else if (sideRemaining > baseRemaining) {
        jAhead++;
      } else {
        iAhead++;
      }

      // Scan ahead
      while (iAhead < m && jAhead < n) {
        if (base[iAhead] === side[jAhead]) {
          lenAhead++;
          break;
        }
        const baseRem = m - iAhead;
        const sideRem = n - jAhead;
        if (sideRem > baseRem) {
          jAhead++;
        } else if (baseRem > sideRem) {
          iAhead++;
        } else {
          iAhead++;
        }
      }

      return len + lenAhead;
    }
  }

  return len;
}

function gatherRegions(base, mineChanges, theirsChanges) {
  // Merge changes from both sides into one list
  const allChanges = [];

  for (const change of mineChanges) {
    allChanges.push({ ...change, side: 'mine' });
  }

  for (const change of theirsChanges) {
    allChanges.push({ ...change, side: 'theirs' });
  }

  // Sort by baseStart, with mine before theirs when equal
  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) {
      return a.baseStart - b.baseStart;
    }
    return a.side === 'mine' ? -1 : 1;
  });

  // Gather into regions by absorbing overlapping changes
  const regions = [];
  let i = 0;

  // Add initial stable region if needed
  if (allChanges.length === 0) {
    return [{ type: 'stable', baseStart: 0, baseEnd: base.length }];
  }

  if (allChanges[0].baseStart > 0) {
    regions.push({ type: 'stable', baseStart: 0, baseEnd: allChanges[0].baseStart });
  }

  while (i < allChanges.length) {
    // Start a new region
    let regionStart = allChanges[i].baseStart;
    let regionEnd = allChanges[i].baseEnd;
    const mineChangesInRegion = [];
    const theirsChangesInRegion = [];

    if (allChanges[i].side === 'mine') {
      mineChangesInRegion.push(allChanges[i]);
    } else {
      theirsChangesInRegion.push(allChanges[i]);
    }

    i++;

    // Absorb overlapping changes
    while (i < allChanges.length && allChanges[i].baseStart <= regionEnd) {
      const change = allChanges[i];
      regionEnd = Math.max(regionEnd, change.baseEnd);

      if (change.side === 'mine') {
        mineChangesInRegion.push(change);
      } else {
        theirsChangesInRegion.push(change);
      }

      i++;
    }

    // Record the region with its changes
    if (mineChangesInRegion.length === 0) {
      regions.push({
        type: 'theirs',
        changes: theirsChangesInRegion,
        baseStart: regionStart,
        baseEnd: regionEnd
      });
    } else if (theirsChangesInRegion.length === 0) {
      regions.push({
        type: 'mine',
        changes: mineChangesInRegion,
        baseStart: regionStart,
        baseEnd: regionEnd
      });
    } else {
      regions.push({
        type: 'both',
        mineChanges: mineChangesInRegion,
        theirsChanges: theirsChangesInRegion,
        baseStart: regionStart,
        baseEnd: regionEnd
      });
    }

    // Add stable region after this change region if needed
    if (i < allChanges.length && allChanges[i].baseStart > regionEnd) {
      regions.push({
        type: 'stable',
        baseStart: regionEnd,
        baseEnd: allChanges[i].baseStart
      });
    }
  }

  // Add final stable region if needed
  if (allChanges.length > 0 && allChanges[allChanges.length - 1].baseEnd < base.length) {
    regions.push({
      type: 'stable',
      baseStart: allChanges[allChanges.length - 1].baseEnd,
      baseEnd: base.length
    });
  }

  return regions;
}

function resolveRegions(regions, base, mine, theirs) {
  const resolved = [];

  for (const region of regions) {
    if (region.type === 'stable') {
      resolved.push({
        type: 'stable',
        lines: base.slice(region.baseStart, region.baseEnd)
      });
    } else if (region.type === 'mine') {
      // Only mine changed - use mine's lines for the region
      const lines = computeSideLines(base, region.baseStart, region.baseEnd, region.changes, mine);
      resolved.push({
        type: 'mine',
        lines: lines
      });
    } else if (region.type === 'theirs') {
      // Only theirs changed - use theirs's lines for the region
      const lines = computeSideLines(base, region.baseStart, region.baseEnd, region.changes, theirs);
      resolved.push({
        type: 'theirs',
        lines: lines
      });
    } else if (region.type === 'both') {
      // Both sides changed - apply resolution logic
      const mineLines = computeSideLines(base, region.baseStart, region.baseEnd, region.mineChanges, mine);
      const theirsLines = computeSideLines(base, region.baseStart, region.baseEnd, region.theirsChanges, theirs);
      const baseLines = base.slice(region.baseStart, region.baseEnd);

      // Apply resolution logic
      if (linesEqual(mineLines, theirsLines)) {
        // Both made the same change
        resolved.push({
          type: 'mine',
          lines: mineLines
        });
      } else if (linesEqual(mineLines, baseLines)) {
        // Mine equals base, so theirs changed
        resolved.push({
          type: 'theirs',
          lines: theirsLines
        });
      } else if (linesEqual(theirsLines, baseLines)) {
        // Theirs equals base, so mine changed
        resolved.push({
          type: 'mine',
          lines: mineLines
        });
      } else {
        // Conflict
        resolved.push({
          type: 'conflict',
          mine: mineLines,
          base: baseLines,
          theirs: theirsLines
        });
      }
    }
  }

  return resolved;
}

function computeSideLines(base, regionStart, regionEnd, changes, side) {
  // Compute what the side's view of the region looks like
  // by applying changes to the base region
  const result = [];
  const sortedChanges = changes.slice().sort((a, b) => a.baseStart - b.baseStart);

  let baseIdx = regionStart;

  for (const change of sortedChanges) {
    // Add unchanged base lines before this change
    for (let i = baseIdx; i < change.baseStart; i++) {
      result.push(base[i]);
    }
    // Add changed lines from side
    for (let i = change.sideStart; i < change.sideEnd; i++) {
      result.push(side[i]);
    }
    baseIdx = change.baseEnd;
  }

  // Add remaining unchanged base lines
  for (let i = baseIdx; i < regionEnd; i++) {
    result.push(base[i]);
  }

  return result;
}

function linesEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

