/**
 * Match the two documents line by line with a longest common subsequence.
 * Ties are broken toward the earliest matches: at each step take a match when
 * the current lines are equal, otherwise advance the side whose remaining
 * subsequence is at least as long as the other's, preferring the base.
 * Returns the list of matched index pairs.
 */
export function matchLines(base, side) {
  const m = base.length
  const n = side.length

  // lengths[i][j] is the length of the longest common subsequence of
  // base[i..] and side[j..].
  const lengths = new Array(m + 1)
  for (let i = 0; i <= m; i++) lengths[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    const row = lengths[i]
    const next = lengths[i + 1]
    for (let j = n - 1; j >= 0; j--) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push({ base: i, side: j })
      i++
      j++
    } else if (lengths[i + 1][j] >= lengths[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Every stretch the subsequence does not cover, as a run of base lines
 * replaced by a run of the side's lines.
 */
export function changesAgainst(base, side) {
  const changes = []
  let baseAt = 0
  let sideAt = 0

  const record = (baseEnd, sideEnd) => {
