 * The three-way merge itself: regions of the base and how each resolves.
 */

import { changesAgainst } from './diff.js'

/**
 * Gather the changes of both sides into regions of the base.
 * Returns stable and changed regions covering the base in order.
 */
function gatherRegions(base, mineChanges, theirsChanges) {
  const all = []
  for (const change of mineChanges) all.push({ ...change, side: 'mine' })
  for (const change of theirsChanges) all.push({ ...change, side: 'theirs' })
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let covered = 0
  let index = 0
  while (index < all.length) {
    const first = all[index]
    let start = first.baseStart
    let end = first.baseEnd
    const mine = []
    const theirs = []
    const add = change => (change.side === 'mine' ? mine : theirs).push(change)
    add(first)
    index++
    while (index < all.length && all[index].baseStart <= end) {
      const change = all[index]
      if (change.baseEnd > end) end = change.baseEnd
      add(change)
      index++
    }
    if (start > covered) regions.push({ kind: 'stable', start: covered, end: start })
    regions.push({ kind: 'changed', start, end, mine, theirs })
    covered = end
  }
  if (covered < base.length || regions.length === 0) {
    regions.push({ kind: 'stable', start: covered, end: base.length })
  }
  return regions
}

/**
 * A side's replacement for a region: from the smallest start of its own
 * changes, moved back by however far the region begins before them, to the
 * largest end of its own changes, moved forward by however far the region
 * ends after them.
 */
function sideLines(region, changes, base, side) {
  if (changes.length === 0) return base.slice(region.start, region.end)
  let baseStart = Infinity
  let baseEnd = -Infinity
  let start = Infinity
  let end = -Infinity
  for (const change of changes) {
    if (change.baseStart < baseStart) baseStart = change.baseStart
    if (change.baseEnd > baseEnd) baseEnd = change.baseEnd
    if (change.sideStart < start) start = change.sideStart
    if (change.sideEnd > end) end = change.sideEnd
  }
  return side.slice(start - (baseStart - region.start), end + (region.end - baseEnd))
}

function sameLines(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}

/**
 * Resolve the whole merge into a list of resolved regions, each either
 * `{ kind: 'stable' | 'mine' | 'theirs' | 'both', lines }` or
 * `{ kind: 'conflict', mine, base, theirs }`.
 */
export function mergeDocuments(mine, base, theirs) {
  const regions = gatherRegions(base, changesAgainst(base, mine), changesAgainst(base, theirs))
  const resolved = []

  for (const region of regions) {
    if (region.kind === 'stable') {
      resolved.push({ kind: 'stable', lines: base.slice(region.start, region.end) })
      continue
    }
    const baseLines = base.slice(region.start, region.end)
    const mineLines = sideLines(region, region.mine, base, mine)
    const theirsLines = sideLines(region, region.theirs, base, theirs)

    if (region.theirs.length === 0) {
      resolved.push({ kind: 'mine', lines: mineLines })
    } else if (region.mine.length === 0) {
      resolved.push({ kind: 'theirs', lines: theirsLines })
    } else if (sameLines(mineLines, theirsLines)) {
      resolved.push({ kind: 'both', lines: mineLines })
    } else if (sameLines(mineLines, baseLines)) {
      resolved.push({ kind: 'theirs', lines: theirsLines })
    } else if (sameLines(theirsLines, baseLines)) {
      resolved.push({ kind: 'mine', lines: mineLines })
    } else {
      resolved.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }
  }

  return resolved
}
"}

