 * Resolve the whole merge into a list of resolved regions, each either
 * `{ kind: 'stable' | 'mine' | 'theirs' | 'both', lines }` or
 * `{ kind: 'conflict', mine, base, theirs }`.
 */
export function mergeDocuments(mine, base, theirs) {
  const regions = gatherRegions(base, changesAgainst(base, mine), changesAgainst(base, theirs))
  const resolved = []

  for (const region of regions) {
    if (region.kind === 'stable') {
      resolved.push({ kind: 'stable', lines: base.slice(region.start, region.end) })
      continue
    }
    const baseLines = base.slice(region.start, region.end)
    const mineLines = sideLines(region, region.mine, base, mine)
    const theirsLines = sideLines(region, region.theirs, base, theirs)

    if (region.theirs.length === 0) {
      resolved.push({ kind: 'mine', lines: mineLines })
    } else if (region.mine.length === 0) {
      resolved.push({ kind: 'theirs', lines: theirsLines })
    } else if (sameLines(mineLines, theirsLines)) {
      resolved.push({ kind: 'both', lines: mineLines })
    } else if (sameLines(mineLines, baseLines)) {
      resolved.push({ kind: 'theirs', lines: theirsLines })
    } else if (sameLines(theirsLines, baseLines)) {
      resolved.push({ kind: 'mine', lines: mineLines })
    } else {
