const alpha=['a','b','c','d']
const rnd=n=>Array.from({length:n},()=>alpha[Math.floor(Math.random()*alpha.length)])
const mut=doc=>{const d=doc.slice();const k=1+Math.floor(Math.random()*3);for(let q=0;q<k;q++){const r=Math.random();const p=Math.floor(Math.random()*(d.length+1));if(r<0.4)d.splice(p,0,alpha[Math.floor(Math.random()*alpha.length)]);else if(r<0.7&&d.length)d.splice(p%d.length,1);else if(d.length)d[p%d.length]=alpha[Math.floor(Math.random()*alpha.length)]}return d}
